def predict_one(tree, x):
""" Faz a predição para um único exemplo x, usando a árvore 'tree'."""
# Se for um nó folha (valor inteiro)
if not isinstance(tree, dict):
return tree
feature = tree['feature']
threshold = tree['threshold']
if x[feature] <= threshold:
return predict_one(tree['left'], x)
else:
return predict_one(tree['right'], x)
def predict(tree, X):
""“ Faz a predição de um conjunto de amostras X (matriz).
Retorna uma lista ou array de rótulos previstos. """
y_pred = []
for i in range(len(X)):
y_pred.append(predict_one(tree, X[i]))
return np.array(y_pred)

